    b = predicted.shape[0]
    n = 1
    for d in predicted.shape[1:]:
        n *= d
    lanes = _pick_lanes(n)
    r = n // lanes
    tm = _pick_rows(r, lanes, jnp.dtype(predicted.dtype).itemsize)
    fold = (tm % 8 == 0)
    nk = r // tm
    p3 = predicted.reshape(b, r, lanes)
    t3 = target.reshape(b, r, lanes)
    acc_rows = 8 if fold else 1
    kern = functools.partial(_dice_kernel, nb=b, nk=nk, tm=tm, lanes=lanes, fold=fold)
    out = pl.pallas_call(
        kern,
        out_shape=jax.ShapeDtypeStruct((1, 1), jnp.float32),
        grid=(b, nk),
        in_specs=[
            pl.BlockSpec((1, tm, lanes), lambda i, k: (i, k, 0)),
            pl.BlockSpec((1, tm, lanes), lambda i, k: (i, k, 0)),
        ],
        out_specs=pl.BlockSpec((1, 1), lambda i, k: (0, 0)),
        scratch_shapes=[
            pltpu.VMEM((acc_rows, lanes), jnp.float32),
            pltpu.VMEM((acc_rows, lanes), jnp.float32),
            pltpu.VMEM((acc_rows, lanes), jnp.float32),
            pltpu.VMEM((1, 1), jnp.float32),
        ],
        compiler_params=pltpu.CompilerParams(dimension_semantics=("arbitrary", "arbitrary")),
    )(p3, t3)
    return out.reshape(())

