from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _shift(a, dw):
    # a: (W, C). dw == 0 reads column w-1, dw == 1 column w, dw == 2 column w+1.
    if dw == 1:
        return a
    zeros = jnp.zeros((1, a.shape[1]), a.dtype)
    if dw == 0:
        return jnp.concatenate([zeros, a[:-1]], axis=0)
    return jnp.concatenate([a[1:], zeros], axis=0)


def _conv_row(read_row, w_ref, r):
    acc = None
    for dh in range(3):
        row = read_row(r + dh)
        for dw in range(3):
            d = jnp.dot(_shift(row, dw), w_ref[dh, dw],
                        preferred_element_type=jnp.float32)
            acc = d if acc is None else acc + d
    return acc


def _kernel(x_ref, top_ref, bot_ref, w1_ref, w2_ref, o_ref, h1_ref, *, bh, nh):
    i = pl.program_id(1)
    has_top = jnp.where(i > 0, 1.0, 0.0).astype(jnp.float32)
    has_bot = jnp.where(i < nh - 1, 1.0, 0.0).astype(jnp.float32)

    def read_x(t):
        if t < 2:
            return top_ref[0, t]
        if t < bh + 2:
            return x_ref[0, t - 2]
        return bot_ref[0, t - 2 - bh]

    rows = bh + 2
    for r in range(rows):
        y = jnp.maximum(_conv_row(read_x, w1_ref, r), 0.0)
        if r == 0:
            y = y * has_top
        elif r == rows - 1:
            y = y * has_bot
        h1_ref[r] = y

    def read_h1(t):
        return h1_ref[t]

    for r in range(bh):
        y = jnp.maximum(_conv_row(read_h1, w2_ref, r), 0.0)
        o_ref[0, r] = y.astype(o_ref.dtype)


def _num_slabs(h, w, c):
    for d in (1, 2, 4, 8, 16, 32):
        if h % d == 0 and (h // d) * w * c * 4 <= (1 << 20):
            return d
    return h


def workload(x, w1, w2):
    b, c, h, w = x.shape
    o = w2.shape[0]
    nh = _num_slabs(h, w, max(c, o))
    bh = h // nh

    xt = jnp.transpose(x, (0, 2, 3, 1))
    xp = jnp.pad(xt, ((0, 0), (2, 2), (0, 0), (0, 0)))
    top = jnp.concatenate(
        [xp[:, s * bh:s * bh + 2, :, :] for s in range(nh)], axis=1)
    bot = jnp.concatenate(
        [xp[:, (s + 1) * bh + 2:(s + 1) * bh + 4, :, :] for s in range(nh)], axis=1)

    w1t = jnp.transpose(w1, (2, 3, 1, 0))
    w2t = jnp.transpose(w2, (2, 3, 1, 0))

    out = pl.pallas_call(
        functools.partial(_kernel, bh=bh, nh=nh),
        out_shape=jax.ShapeDtypeStruct((b, h, w, o), x.dtype),
        grid=(b, nh),
        in_specs=[
            pl.BlockSpec((1, bh, w, c), lambda n, s: (n, s, 0, 0)),
            pl.BlockSpec((1, 2, w, c), lambda n, s: (n, s, 0, 0)),
            pl.BlockSpec((1, 2, w, c), lambda n, s: (n, s, 0, 0)),
            pl.BlockSpec(w1t.shape, lambda n, s: (0, 0, 0, 0)),
            pl.BlockSpec(w2t.shape, lambda n, s: (0, 0, 0, 0)),
        ],
        out_specs=pl.BlockSpec((1, bh, w, o), lambda n, s: (n, s, 0, 0)),
        scratch_shapes=[pltpu.VMEM((bh + 2, w, w1.shape[0]), jnp.float32)],
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel")),
    )(xt, top, bot, w1t, w2t)
    return jnp.transpose(out, (0, 3, 1, 2))

